# Build Modbus Slave .mbs for vgpoint_scene_room (7 slaves).
# Requires Modbus Slave (Mbslave.Application COM) on Windows.
#
# Usage:
#   .\build_scene_room_mbslaves.ps1
#   .\build_scene_room_mbslaves.ps1 -ComPort 4

param(
  [int]$ComPort = 4,
  [int]$Baud = 9600,
  [string]$OutDir = $PSScriptRoot
)

$ErrorActionPreference = "Stop"
$csvPath = Join-Path $OutDir "scene_slaves.csv"

function Get-SafeSensorName([string]$Name) {
  $n = $Name -replace '^\[S\]', ''
  $n = $n.Trim()
  foreach ($c in @('<', '>', ':', '"', '/', '\', '|', '?', '*')) {
    $n = $n.Replace($c, '_')
  }
  $n = $n -replace '\s+', ''
  if ([string]::IsNullOrWhiteSpace($n)) { $n = 'sensor' }
  return $n
}

if (-not (Test-Path $csvPath)) {
  throw "Missing $csvPath"
}

New-Item -ItemType Directory -Force -Path $OutDir | Out-Null
$slaves = Import-Csv $csvPath

Write-Output "=== Modbus Slave: scene_room $($slaves.Count) slaves, COM$ComPort @ $Baud 8N1 ==="
Write-Output "OutDir: $OutDir"

try {
  $app = New-Object -ComObject Mbslave.Application
}
catch {
  throw "Mbslave.Application COM failed. Install Modbus Slave and run it once."
}

$app.Connection = 0
$app.SerialPort = $ComPort
$app.BaudRate = $Baud
$app.DataBits = 8
$app.Parity = 0
$app.StopBits = 1
try { $app.Mode = 0 } catch {}

$docs = @()
foreach ($s in $slaves) {
  $addr = [int]$s.addr
  $qty = [int]$s.holding_qty
  $name = $s.name
  $mbs = Join-Path $OutDir ("{0:D2}_{1}.mbs" -f $addr, (Get-SafeSensorName $name))

  $doc = New-Object -ComObject Mbslave.Document
  $ok = $doc.SetupHoldingRegisters($addr, 0, $qty)
  if (-not $ok) {
    throw "SetupHoldingRegisters failed addr=$addr qty=$qty"
  }

  $doc.EnableRefresh = $false

  # Apply multi-register seeds: "0:250;1:550"
  $seedMap = @{}
  if ($s.seeds) {
    foreach ($pair in ($s.seeds -split ';')) {
      if ([string]::IsNullOrWhiteSpace($pair)) { continue }
      $parts = $pair.Split(':')
      if ($parts.Count -ge 2) {
        $seedMap[[int]$parts[0]] = [int]$parts[1]
      }
    }
  }
  if ($seedMap.Count -eq 0) {
    $seedMap[[int]$s.seed_reg] = [int]$s.seed_value
  }

  # Prefer "空调运行" offline seed as running (1) when square mock starts at 0.
  if ($addr -eq 4 -and $seedMap.ContainsKey(2) -and $seedMap[2] -eq 0) {
    $seedMap[2] = 1
  }

  foreach ($reg in ($seedMap.Keys | Sort-Object)) {
    if ($reg -ge 0 -and $reg -lt $qty) {
      $doc.URegisters($reg) = [int]$seedMap[$reg]
    }
  }

  try {
    $doc.Save($mbs)
  }
  catch {
    Write-Warning "COM Save not available for addr=$addr — save manually: $mbs"
  }

  $docs += [pscustomobject]@{ Addr = $addr; Name = $name; Qty = $qty; File = $mbs; Doc = $doc }
  $seedText = ($seedMap.GetEnumerator() | Sort-Object Name | ForEach-Object { "$($_.Key)=$($_.Value)" }) -join ','
  Write-Output ("addr={0,2} qty={1,2} seeds=[{2}] -> {3}" -f $addr, $qty, $seedText, (Split-Path $mbs -Leaf))
}

Write-Output ""
Write-Output "Done. Open with: .\open_scene_room_mbslaves.cmd"
Write-Output "Or: .\open_scene_room_mbslaves.ps1 -OpenConnection"

# Release docs so files are not locked by this build process.
for ($i = $docs.Count - 1; $i -ge 0; $i--) {
  try { [void][System.Runtime.InteropServices.Marshal]::FinalReleaseComObject($docs[$i].Doc) } catch {}
}
try { [void][System.Runtime.InteropServices.Marshal]::FinalReleaseComObject($app) } catch {}
[GC]::Collect()
[GC]::WaitForPendingFinalizers()

# Open vgpoint_scene_room Modbus Slave windows (01..07_*.mbs).
#
# IMPORTANT: Mbslave.Document COM windows are owned by this process.
# Keep this console open until finished — closing it closes all slave windows.
#
# Usage:
#   .\open_scene_room_mbslaves.ps1
#   .\open_scene_room_mbslaves.ps1 -ComPort 4 -OpenConnection
#   .\open_scene_room_mbslaves.ps1 -KeepOpenSeconds 3600 -OpenConnection

param(
  [string]$Dir = $PSScriptRoot,
  [int]$ComPort = 4,
  [int]$Baud = 9600,
  [switch]$OpenConnection,
  [int]$KeepOpenSeconds = 0
)

$ErrorActionPreference = "Stop"

function Get-SafeSensorName([string]$Name) {
  $n = $Name -replace '^\[S\]', ''
  $n = $n.Trim()
  foreach ($c in @('<', '>', ':', '"', '/', '\', '|', '?', '*')) {
    $n = $n.Replace($c, '_')
  }
  $n = $n -replace '\s+', ''
  if ([string]::IsNullOrWhiteSpace($n)) { $n = 'sensor' }
  return $n
}

function Resolve-SlaveMbs([string]$Root, [int]$Addr, [string]$Name) {
  $safe = Get-SafeSensorName $Name
  $named = Join-Path $Root ("{0:D2}_{1}.mbs" -f $Addr, $safe)
  if (Test-Path $named) { return $named }
  return $null
}

if (-not (Test-Path $Dir)) {
  throw "Directory not found: $Dir"
}
$Dir = (Resolve-Path $Dir).Path
$csvPath = Join-Path $Dir "scene_slaves.csv"

$files = @()
if (Test-Path $csvPath) {
  foreach ($s in (Import-Csv $csvPath)) {
    $addr = [int]$s.addr
    $path = Resolve-SlaveMbs $Dir $addr $s.name
    if (-not $path) { throw "Missing mbs for addr=$addr under $Dir (run build_scene_room_mbslaves.ps1 first)" }
    $files += [pscustomobject]@{ Addr = $addr; Name = $s.name; File = $path }
  }
}
else {
  $named = Get-ChildItem -Path $Dir -Filter "*.mbs" |
    Where-Object { $_.Name -match '^\d{2}_.+\.mbs$' } |
    Sort-Object Name
  if ($named.Count -eq 0) {
    throw "No NN_<sensor>.mbs in $Dir — run build_scene_room_mbslaves.ps1 first"
  }
  foreach ($f in $named) {
    $files += [pscustomobject]@{
      Addr = [int]$f.BaseName.Substring(0, 2)
      Name = $f.BaseName
      File = $f.FullName
    }
  }
}

$files = @($files | Sort-Object Addr)
Write-Output "=== Open $($files.Count) scene_room Modbus Slave docs from $Dir ==="
Write-Output "NOTE: keep this console open — closing it closes all slave windows."

try {
  $app = New-Object -ComObject Mbslave.Application
}
catch {
  throw "Mbslave.Application COM failed. Install Modbus Slave and run it once."
}

$app.Connection = 0
$app.SerialPort = $ComPort
$app.BaudRate = $Baud
$app.DataBits = 8
$app.Parity = 0
$app.StopBits = 1
try { $app.Mode = 0 } catch {}

$docs = New-Object System.Collections.ArrayList
foreach ($f in $files) {
  $doc = New-Object -ComObject Mbslave.Document
  $ok = $false
  try { $ok = [bool]$doc.Open([string]$f.File) } catch {}
  if (-not $ok) {
    throw "Failed to open $($f.File)"
  }
  try { $doc.ShowWindow() | Out-Null } catch {}
  [void]$docs.Add($doc)
  Write-Output ("addr={0,2} opened {1}" -f $f.Addr, (Split-Path $f.File -Leaf))
}

if ($OpenConnection) {
  $st = $app.OpenConnection()
  Write-Output "OpenConnection status=$st (COM$ComPort @ $Baud 8N1)"
}
else {
  Write-Output ""
  Write-Output "Serial not opened by script. In Modbus Slave: Connection -> COM$ComPort @ $Baud 8N1 -> Connect"
  Write-Output "Or re-run with: -OpenConnection"
}

Write-Output ""
Write-Output "Holding $($docs.Count) windows alive via COM."
try {
  if ($KeepOpenSeconds -gt 0) {
    Write-Output "Auto-exit in ${KeepOpenSeconds}s (Ctrl+C sooner)..."
    Start-Sleep -Seconds $KeepOpenSeconds
  }
  else {
    Write-Host -ForegroundColor Yellow "Press Enter here when finished (windows will then close)."
    [void][System.Console]::ReadLine()
  }
}
finally {
  Write-Output "Releasing COM docs..."
  try { $app.CloseConnection() | Out-Null } catch {}
  for ($i = $docs.Count - 1; $i -ge 0; $i--) {
    try { [void][System.Runtime.InteropServices.Marshal]::FinalReleaseComObject($docs[$i]) } catch {}
  }
  try { [void][System.Runtime.InteropServices.Marshal]::FinalReleaseComObject($app) } catch {}
  [GC]::Collect()
  [GC]::WaitForPendingFinalizers()
}

